package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/** The figure a claim shows and totals: the due fixed when it was settled, else the greater of the
 *  sheet's floor in force on the claim's date and its figure plus its late charge, where its figure is
 *  the one its person's last statement bound it to, else live at its person's grade's rate in force on
 *  the claim's date (null, n/a, when there is no rate). A correction has neither floor nor charge. Every rounding of a claim's live figures follows
 *  the sheet's rounding mode in force on the claim's date, else the sheet's policy date: half up for a claim dated before it, half to even on or after it. */
@Service
public class Figures {

    private final Rates rates;
    private final Settings settings;
    private final Sheets sheets;
    private final Claims claims;

    public Figures(Rates rates, Settings settings, Sheets sheets, Claims claims) {
        this.rates = rates;
        this.settings = settings;
        this.sheets = sheets;
        this.claims = claims;
    }

    /** The sheet's policy date: as set, else the sheet's today. */
    public LocalDate policyDate(String sheetId) {
        LocalDate set = settings.policyDate(sheetId);
        return set != null ? set : sheets.today(sheetId);
    }

    /** How the claim's live figures round: by the sheet's rounding mode in force on the claim's
     *  (rounding) date when one is; else half up when the claim is dated before the sheet's policy
     *  date, half to even on or after it. A correction rounds by the date of the claim it corrects. */
    public RoundingMode rounding(Claim claim) {
        RoundingMode set = settings.rounding(claim.getSheetId(), roundingDate(claim));
        if (set != null) return set;
        return roundingDate(claim).isBefore(policyDate(claim.getSheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The date the claim rounds by: its own, or for a correction that of the claim it corrects. */
    public LocalDate roundingDate(Claim claim) {
        if (claim.getCorrects() == null) return claim.getDate();
        LocalDate corrected = claims.dateOf(claim.getSheetId(), claim.getPersonId(), claim.getCorrects());
        return corrected != null ? corrected : claim.getDate();
    }

    /** The claim's due as the screen shows and totals it: its figure plus its late charge while it
     *  is overdue, raised to the sheet's floor in force on the claim's date when it is below it (a
     *  correction has neither). A settled claim's fixed due already holds the charge and floor it had then. */
    public BigDecimal due(Claim claim, String grade) {
        BigDecimal figure = figure(claim, grade);
        if (figure == null || claim.getDue() != null || claim.isCorrection()) return figure;
        return figure.add(charge(claim, grade, figure)).max(settings.floor(claim.getSheetId(), claim.getDate()));
    }

    /** The claim's figure without any late charge or floor: the fixed due, else the bound figure, else live.
     *  A PENDING claim is not bound by a statement: it keeps its binding but shows its live figure. */
    public BigDecimal figure(Claim claim, String grade) {
        if (claim.getDue() != null) return claim.getDue();
        if (claim.isStated() && claim.getStatus() != ClaimStatus.PENDING) return claim.getStatedDue();
        return live(claim, grade);
    }

    /** The date the claim goes overdue after: its due-by (fixed when it was added) plus the grace days
     *  of its person's grade in force on the claim's date (`grade`), in force on that date. */
    public LocalDate overdueFrom(Claim claim, String grade) {
        return claim.getDueBy().plusDays(settings.grace(claim.getSheetId(), grade, claim.getDate()));
    }

    /** Whether the claim is overdue: OPEN (or PENDING), not deferred, and its due-by plus its grace
     *  (see {@link #overdueFrom}) is before the sheet's today. */
    public boolean overdue(Claim claim, String grade) {
        if (!claim.getStatus().isOpen() || claim.isDeferred()) return false;
        }
        if (change.action() == ClaimAction.SETTLE && change.user().equals(claim.getEditedBy())) {
            throw new ClaimStatusRefusedException("The user who last edited a claim cannot settle it");
        }
        if (change.action() == ClaimAction.APPROVE) {
            if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(change.user())) {
                throw new ClaimStatusRefusedException("The user who opened a claim cannot approve it");
            }
            if (change.user().equals(claim.getEditedBy())) {
                throw new ClaimStatusRefusedException("The user who last edited a claim cannot approve it");
            }
            if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD) {
                throw new ClaimStatusRefusedException("Only a steward can approve a pending claim");
            }
        }
        if (change.action() == ClaimAction.REVIEW && settings.role(claim.getSheetId(), change.user()) != Role.STEWARD) {
            throw new ClaimStatusRefusedException("Only a steward can review a claim");
        }
        boolean review = false;
        if (change.action() == ClaimAction.OPEN) {
            BigDecimal threshold = settings.reviewThreshold(claim.getSheetId(), claim.getDate());
            if (threshold != null) {
                String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
                BigDecimal due = figures.due(claim, grade);
                review = due != null && due.compareTo(threshold) > 0;
            }
        }
        BigDecimal due = null;
        boolean pending = false;
        if (change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE) {
            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
            // Figures.due: from the bound figure for an OPEN claim, the live one for a PENDING claim.
            due = figures.due(claim, grade);
            // Before the clerk limit: a claim refused for want of a proof never goes PENDING.
            BigDecimal threshold = settings.proofThreshold(claim.getSheetId(), grade, claim.getDate());
            if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
                throw new ClaimStatusRefusedException("A claim whose due is over the proof threshold needs a proof");
            }
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            pending = change.action() == ClaimAction.SETTLE && limit != null && due != null && due.compareTo(limit) > 0
                    && settings.role(claim.getSheetId(), change.user()) == Role.CLERK;
        }
        claim.setStatus(pending ? ClaimStatus.PENDING : review ? ClaimStatus.REVIEW : change.action().to());
        // Settled one at a time: in no batch (a bulk settle sets its batch after this).
        if (change.action() == ClaimAction.SETTLE) claim.setBatch(null);
        if (change.action() == ClaimAction.VOID) claim.setVoidReason(voidReason);
        if (change.action() == ClaimAction.OPEN) {
            // A claim gone to REVIEW gets its number only once a steward reviews it.
            if (!review) claim.setNumber(numbers.next(claim));
            claim.setOpenedBy(change.user());
        }
        if (change.action() == ClaimAction.REVIEW) claim.setNumber(numbers.next(claim));
        if ((change.action() == ClaimAction.SETTLE && !pending) || change.action() == ClaimAction.APPROVE) {
            claim.setDue(due);
        }
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Takes the person's statement: their due-total now, the sum of their counting claims' figures
 *  with any late charges, each at least the floor (n/a when there is no rate today and none has a figure), at most the sheet's cap, dated the sheet's today. Every claim
 *  of theirs that counts (not an OPEN one dated within one of their holds) is bound to its rate figure now, without its late charge or the floor; every other one is unbound.
 *  Taken as of a date (on or before the sheet's today), all of it is worked out on the sheet as it
 *  stood at the end of that date (see {@link AsOf}): the claims that counted then are bound to their
 *  figures then, and the statement is dated that date. Refused: a date after the sheet's today, or
 *  one the person was not yet on the sheet. */
public class TakeStatement {
    public void take(@Val StatementRequest request, @Val Person person, Claims claims, Figures figures,
            Rates rates, Sheets sheets, Settings settings, People people, AsOf asOf, Out<Statement> statement)
            throws InvalidSheetRequestException {
        LocalDate date = asOfDate(request);
        String sheetId = person.getSheetId();
        if (date != null && date.isAfter(sheets.today(sheetId))) {
            throw new InvalidSheetRequestException("A statement cannot be taken as of a date after the sheet's today");
        }
        Person locked = people.lock(sheetId, person.getId());
        person.setStatementCount(locked.getStatementCount());
        Taken taken = date == null ? work(person, claims, figures, rates, sheets, settings)
                : asOf.at(sheetId, date, () -> {
                    Person then = people.find(sheetId, person.getId());
                    return then == null ? null : work(then, claims, figures, rates, sheets, settings);
                });
        if (taken == null) {
            throw new InvalidSheetRequestException("This person was not on the sheet on " + date);
        }
        for (Claim claim : claims.ofPerson(sheetId, person.getId())) {
            boolean bound = taken.bound().containsKey(claim.getId());
            claim.setStated(bound);
            claim.setStatedDue(bound ? taken.bound().get(claim.getId()) : null);
            claims.save(claim);
        }
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(taken.dueTotal());
        person.setStatementDate(taken.date());
        people.saveStatement(person);
        statement.set(new Statement(taken.dueTotal(), taken.bound().size(), request.user(), date));
    }

    /** The statement of the person as the sheet stands (live, or as of a date): the figure each
     *  counting claim is bound to, by id, and their due-total, dated the sheet's today. */
    private static Taken work(Person person, Claims claims, Figures figures, Rates rates, Sheets sheets,
            Settings settings) {
        String sheetId = person.getSheetId();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean any = false;
        Map<Long, BigDecimal> bound = new HashMap<>();
        for (Claim claim : claims.ofPerson(sheetId, person.getId())) {
            if (person.counts(claim)) {
                // The statement binds the rate figure; the late charge and floor on top keep following today.
                bound.put(claim.getId(), figures.figure(claim, person.gradeOn(claim.getDate())));
                BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
                if (figure != null) {
                    total = total.add(figure);
                    any = true;
                }
            }
        }
        LocalDate today = sheets.today(sheetId);
        BigDecimal dueTotal = !any && rates.pct(sheetId, person.gradeOn(today), today) == null ? null
                : settings.capped(sheetId, total);
        return new Taken(bound, dueTotal, today);
    }

    /** The date the statement is taken as of; null when none was given. */
    private static LocalDate asOfDate(StatementRequest request) throws InvalidSheetRequestException {
        String text = request.asOf();
        if (text == null || text.isBlank()) return null;
        try {
            return LocalDate.parse(text.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date: " + text);
        }
    }

    private record Taken(Map<Long, BigDecimal> bound, BigDecimal dueTotal, LocalDate date) {
    }
}

